#!/usr/bin/env bash
#
# Dev-worktree setup wizard for Tavi.
# Generated by the /wizard skill. Run once inside each new git worktree.
#
# It copies the shared secrets out of ~/.config/tavi/dev.env, gives this
# worktree its own API/web ports and PostgreSQL database so worktrees can run
# side by side, installs dependencies, applies migrations, and can start
# `pnpm dev`.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# ---------------------------------------------------------------------------
# This wizard's own configuration and helpers.
# ---------------------------------------------------------------------------

# Shared secrets live in one vault, not in any worktree.
VAULT="${TAVI_ENV_VAULT:-$HOME/.config/tavi/dev.env}"
API_ENV="apps/api/.env"
API_ENV_SAMPLE="apps/api/.env.sample"
WEB_ENV="apps/web/.env.development.local"
NATIVE_ENV="apps/native/.env.local"
NATIVE_ENV_SAMPLE="apps/native/.env.example"

# Values every worktree shares. Per-worktree ports and database are derived.
VAULT_KEYS=(
  AUTH_SECRET
  GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET
  GITHUB_CLIENT_ID GITHUB_CLIENT_SECRET
  RESEND_API_KEY RESEND_FROM_EMAIL
  SENTRY_DSN
)

# Port families. Slot 0 is the canonical checkout's defaults; worktrees claim
# the lowest free slot, so 1337/5173/8081 stay with the main checkout and a
# worktree's first slot is 1338/5174/8082.
API_BASE=1337
WEB_BASE=5173
METRO_BASE=8081
SLOT_MIN=1
SLOT_MAX=49

# die MESSAGE: hard stop with a clear next step.
die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

# repo_root: absolute path of this worktree's root.
repo_root() { git rev-parse --show-toplevel 2>/dev/null; }

# main_worktree: the canonical checkout (first entry in `git worktree list`).
main_worktree() {
  git worktree list --porcelain 2>/dev/null | awk '/^worktree /{print substr($0,10); exit}'
}

# vault_get KEY → value from the vault, or empty.
vault_get() {
  [[ -f "$VAULT" ]] || return 0
  local line
  line=$(grep -E "^$1=" "$VAULT" 2>/dev/null | tail -n1) || return 0
  printf '%s' "${line#*=}"
}

# strip_quotes VALUE → VALUE without one layer of matching surrounding quotes.
strip_quotes() {
  local v="$1" first last
  if [[ ${#v} -ge 2 ]]; then
    first="${v:0:1}"; last="${v: -1}"
    if { [[ "$first" == '"' ]] || [[ "$first" == "'" ]]; } && [[ "$first" == "$last" ]]; then
      v="${v:1:${#v}-2}"
    fi
  fi
  printf '%s' "$v"
}

# read_value FILE KEY → KEY's value in FILE, quotes stripped.
read_value() {
  [[ -f "$1" ]] || return 0
  local line
  line=$(grep -E "^$2=" "$1" 2>/dev/null | tail -n1) || return 0
  strip_quotes "${line#*=}"
}

# seed_vault_from FILE: fill empty vault keys from FILE (e.g. the main checkout).
seed_vault_from() {
  local src="$1" key val
  [[ -f "$src" ]] || return 0
  for key in "${VAULT_KEYS[@]}"; do
    if [[ -z "$(vault_get "$key")" ]]; then
      val=$(read_value "$src" "$key")
      if [[ -n "$val" ]]; then
        ENV_FILE="$VAULT"; write_env "$key" "$val"
      fi
    fi
  done
}

# gen_secret: 32 random bytes as hex, for AUTH_SECRET.
gen_secret() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 32
  else
    node -e 'console.log(require("crypto").randomBytes(32).toString("hex"))'
  fi
}

# port_in_use PORT: true when something is already listening on PORT.
port_in_use() {
  if command -v ss >/dev/null 2>&1; then
    ss -ltn 2>/dev/null | awk 'NR>1{print $4}' | grep -qE "[:.]$1$"
  elif command -v lsof >/dev/null 2>&1; then
    lsof -iTCP:"$1" -sTCP:LISTEN >/dev/null 2>&1
  else
    return 1
  fi
}

# Ports already claimed by sibling worktrees, so a slot is never handed out
# twice even when the sibling's dev server is stopped.
declare -A USED_APIS=() USED_WEBS=()
gather_used_ports() {
  local root="$1" path p
  while IFS= read -r path; do
    if [[ -n "$path" && "$path" != "$root" ]]; then
      p=$(read_value "$path/$API_ENV" PORT)
      if [[ "$p" =~ ^[0-9]+$ ]]; then USED_APIS[$p]=1; fi
      p=$(read_value "$path/$WEB_ENV" VITE_DEV_PORT)
      if [[ "$p" =~ ^[0-9]+$ ]]; then USED_WEBS[$p]=1; fi
    fi
  done < <(git worktree list --porcelain | awk '/^worktree /{print substr($0,10)}')
  # The canonical checkout's defaults are always reserved.
  USED_APIS[$API_BASE]=1
  USED_WEBS[$WEB_BASE]=1
}

# summary: accurate close across the three files this wizard writes.
summary() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  note "secrets   $VAULT"
  note "api env   $API_ENV  (PORT=$api_port, DATABASE_URL=$db_name)"
  note "web env   $WEB_ENV  (VITE_DEV_PORT=$web_port)"
  note "native env   $NATIVE_ENV  (RCT_METRO_PORT=$metro_port)"
  printf '\n'
  say "API  http://localhost:$api_port"
  say "Web  http://localhost:$web_port"
  say "Next: pnpm dev"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────

banner "Tavi dev worktree"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight"
root=$(repo_root || true)
if [[ -z "$root" ]]; then die "Not inside a git repository."; fi
cd "$root"

command -v node >/dev/null 2>&1 || die "Node.js 22+ is required (https://nodejs.org)."
node_major=$(node -p 'process.versions.node.split(".")[0]')
if (( node_major < 22 )); then die "Node.js 22+ is required; found $(node -v)."; fi
command -v pnpm >/dev/null 2>&1 || die "pnpm is required (corepack enable && corepack prepare pnpm@11.3.0 --activate)."
command -v docker >/dev/null 2>&1 || die "Docker is required for the local PostgreSQL."
docker info >/dev/null 2>&1 || die "Docker daemon is not running. Start Docker, then re-run."
command -v git >/dev/null 2>&1 || die "git is required."

say "node $(node -v) · pnpm $(pnpm -v) · $(docker --version)"
say "worktree: $root"
pause "Press Enter to continue"

# ── Stage 2: shared secrets ───────────────────────────────────────────────
stage "Shared secrets"
say "Secrets are shared by every worktree and live in a vault outside the repo."
note "  $VAULT"

vault_dir=$(dirname "$VAULT")
mkdir -p "$vault_dir"
chmod 700 "$vault_dir" 2>/dev/null || true
if [[ ! -f "$VAULT" ]]; then
  : > "$VAULT"
fi
chmod 600 "$VAULT" 2>/dev/null || true

# Seed from this worktree's env (re-runs) and then the canonical checkout.
seed_vault_from "$API_ENV"
seed_vault_from "$(main_worktree)/$API_ENV"

if [[ -z "$(vault_get AUTH_SECRET)" ]]; then
  ENV_FILE="$VAULT"; write_env AUTH_SECRET "$(gen_secret)"
  say "Generated a shared AUTH_SECRET."
fi

# Optional providers, only asked for when the vault has no value yet. On a
# normal first run these are seeded from the main checkout, so this is skipped.
if [[ -z "$(vault_get GOOGLE_CLIENT_ID)" && -z "$(vault_get GOOGLE_CLIENT_SECRET)" ]]; then
  if confirm "Configure Google sign-in now? (optional)"; then
    open_url "https://console.cloud.google.com/apis/credentials"
    step "Open your OAuth 2.0 Client ID (create a Web application one if needed)."
    ENV_FILE="$VAULT"
    ask GOOGLE_CLIENT_ID "Google Client ID:"
    if [[ -n "$GOOGLE_CLIENT_ID" ]]; then write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"; fi
    ask_secret GOOGLE_CLIENT_SECRET "Google Client secret:"
    if [[ -n "$GOOGLE_CLIENT_SECRET" ]]; then write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"; fi
  fi
fi

if [[ -z "$(vault_get GITHUB_CLIENT_ID)" && -z "$(vault_get GITHUB_CLIENT_SECRET)" ]]; then
  if confirm "Configure GitHub sign-in now? (optional)"; then
    open_url "https://github.com/settings/developers"
    step "Open your OAuth App and copy the Client ID and Client secret."
    ENV_FILE="$VAULT"
    ask GITHUB_CLIENT_ID "GitHub Client ID:"
    if [[ -n "$GITHUB_CLIENT_ID" ]]; then write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"; fi
    ask_secret GITHUB_CLIENT_SECRET "GitHub Client secret:"
    if [[ -n "$GITHUB_CLIENT_SECRET" ]]; then write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"; fi
  fi
fi

if [[ -z "$(vault_get RESEND_API_KEY)" ]]; then
  if confirm "Configure Resend email now? (optional; invitations need it)"; then
    open_url "https://resend.com/api-keys"
    step "Create/copy an API key, and use a from-address on a verified domain."
    ENV_FILE="$VAULT"
    ask_secret RESEND_API_KEY "Resend API key:"
    if [[ -n "$RESEND_API_KEY" ]]; then write_env RESEND_API_KEY "$RESEND_API_KEY"; fi
    ask RESEND_FROM_EMAIL "From address (e.g. Tavi <noreply@example.com>):"
    if [[ -n "$RESEND_FROM_EMAIL" ]]; then write_env RESEND_FROM_EMAIL "$RESEND_FROM_EMAIL"; fi
  fi
fi

if [[ -z "$(vault_get GOOGLE_CLIENT_ID)" ]]; then
  note "Google/GitHub/Resend left unset; those sign-in and email features stay off."
fi
pause "Press Enter to continue"

# ── Stage 3: worktree identity ────────────────────────────────────────────
stage "Worktree identity"

is_main=""
if [[ "$root" == "$(main_worktree)" ]]; then is_main=1; fi

if [[ -n "$is_main" ]]; then
  # The canonical checkout keeps the documented defaults.
  api_port=$API_BASE
  web_port=$WEB_BASE
  db_name="tavi"
else
  gather_used_ports "$root"
  api_port=""
  web_port=""

  # Reuse a slot this worktree already claimed, so re-runs are stable.
  existing_port=$(read_value "$API_ENV" PORT)
  if [[ "$existing_port" =~ ^[0-9]+$ ]]; then
    api_port="$existing_port"
    web_port=$(read_value "$WEB_ENV" VITE_DEV_PORT)
    if ! [[ "$web_port" =~ ^[0-9]+$ ]]; then web_port=$((WEB_BASE + api_port - API_BASE)); fi
    say "Reusing this worktree's existing slot: API $api_port · web $web_port"
  else
    slot=$SLOT_MIN
    while (( slot <= SLOT_MAX )); do
      api_port=$((API_BASE + slot))
      web_port=$((WEB_BASE + slot))
      if [[ -z "${USED_APIS[$api_port]:-}" && -z "${USED_WEBS[$web_port]:-}" ]] \
        && ! port_in_use "$api_port" && ! port_in_use "$web_port"; then
        break
      fi
      slot=$((slot + 1))
    done
    if (( slot > SLOT_MAX )); then
      die "No free port slot in $SLOT_MIN..$SLOT_MAX. Stop another worktree's dev server, then re-run."
    fi
  fi

  slug=$(printf '%s' "$(basename "$root")" | tr '[:upper:]' '[:lower:]' | sed -E 's/[^a-z0-9]+/_/g; s/^_+//; s/_+$//')
  if [[ -z "$slug" ]]; then slug="worktree"; fi
  db_name="tavi_${slug}"
  db_name="${db_name:0:63}"
fi

# The API, web and Metro ports share one slot number.
slot_num=$((api_port - API_BASE))
metro_port=$((METRO_BASE + slot_num))

# Start from the sample so the commented options stay discoverable.
if [[ ! -f "$API_ENV" && -f "$API_ENV_SAMPLE" ]]; then
  cp "$API_ENV_SAMPLE" "$API_ENV"
fi

ENV_FILE="$API_ENV"
mkdir -p "$(dirname "$API_ENV")" "$(dirname "$WEB_ENV")"
write_env TAVI_APP_NAME "Tavi"
write_env TAVI_API_URL "http://localhost:$api_port"
write_env TAVI_CLIENT_URL "http://localhost:$web_port"
write_env DATABASE_URL "postgresql://tavi:tavi@localhost:5432/$db_name"
write_env PORT "$api_port"
for key in "${VAULT_KEYS[@]}"; do
  value=$(vault_get "$key")
  if [[ -n "$value" ]]; then write_env "$key" "$value"; fi
done

ENV_FILE="$WEB_ENV"
write_env VITE_API_PROXY_TARGET "http://localhost:$api_port"
write_env VITE_DEV_PORT "$web_port"

say "API on :$api_port · web on :$web_port · database $db_name"
say "root .env is not needed for local dev: compose.local.yml hardcodes Postgres."

if [[ -n "$(vault_get GOOGLE_CLIENT_ID)" ]]; then
  step "Google sign-in needs this redirect URI registered for the OAuth client:"
  note "    http://localhost:$api_port/api/auth/callback/google"
  if confirm "Open Google Cloud credentials to add it?"; then
    open_url "https://console.cloud.google.com/apis/credentials"
  fi
fi
pause "Press Enter to continue"

# ── Stage 4: install and database ─────────────────────────────────────────
stage "Install and database"
say "Installing workspace dependencies…"
pnpm install

say "Starting the shared PostgreSQL container…"
docker compose -f compose.local.yml up -d postgres
cid=$(docker compose -f compose.local.yml ps -q postgres)
if [[ -z "$cid" ]]; then die "PostgreSQL container did not start."; fi

health=""
for _ in $(seq 1 30); do
  health=$(docker inspect --format '{{.State.Health.Status}}' "$cid" 2>/dev/null || true)
  if [[ "$health" == "healthy" ]]; then break; fi
  sleep 1
done
if [[ "$health" != "healthy" ]]; then
  die "PostgreSQL did not become healthy (status: ${health:-unknown})."
fi
say "PostgreSQL is healthy."

exists=$(docker compose -f compose.local.yml exec -T postgres \
  psql -U tavi -d postgres -tAc "SELECT 1 FROM pg_database WHERE datname='$db_name'" 2>/dev/null | tr -d '[:space:]' || true)
if [[ "$exists" == "1" ]]; then
  say "Database $db_name already exists."
else
  docker compose -f compose.local.yml exec -T postgres \
    psql -U tavi -d postgres -c "CREATE DATABASE \"$db_name\"" >/dev/null
  say "Created database $db_name."
fi

say "Applying migrations…"
pnpm --filter @tavi/api db:migrate
pause "Press Enter to continue"

# ── Stage 5: native app env ───────────────────────────────────────────────
stage "Native app env"
say "The Expo app reads $NATIVE_ENV; per-worktree ports keep it isolated."

mkdir -p "$(dirname "$NATIVE_ENV")"
native_preexisting=""
if [[ -f "$NATIVE_ENV" ]]; then native_preexisting=1; fi
if [[ -z "$native_preexisting" && -f "$NATIVE_ENV_SAMPLE" ]]; then
  cp "$NATIVE_ENV_SAMPLE" "$NATIVE_ENV"
fi
ENV_FILE="$NATIVE_ENV"

# Keep a previously chosen host (Android emulator / LAN), on this API port.
existing_api=$(read_value "$NATIVE_ENV" EXPO_PUBLIC_API_URL)
existing_host=""
if [[ -n "$existing_api" ]]; then
  existing_host=$(printf '%s' "$existing_api" | sed -E 's#^[A-Za-z][A-Za-z0-9+.-]*://##; s#[:/].*$##')
fi
if [[ -z "$existing_host" ]]; then existing_host="localhost"; fi
write_env EXPO_PUBLIC_API_URL "http://$existing_host:$api_port"
write_env RCT_METRO_PORT "$metro_port"

ask EXPO_PUBLIC_API_URL "API URL reachable from the device (Android emulator: http://10.0.2.2:$api_port, physical device: this machine's LAN IP)"
api_origin=$(printf '%s' "$EXPO_PUBLIC_API_URL" | sed -E 's#^([A-Za-z][A-Za-z0-9+.-]*://[^/]+).*$#\1#')
if [[ "$api_origin" != *://* ]]; then api_origin="http://localhost:$api_port"; fi
web_origin=$(printf '%s' "$api_origin" | sed -E 's#:[0-9]+$##')
write_env EXPO_PUBLIC_API_URL "$api_origin"
write_env EXPO_PUBLIC_WEB_URL "$web_origin:$web_port"

say "EXPO_PUBLIC_API_URL=$api_origin · Metro on :$metro_port"
note "The email preview (packages/email) shifts off :3002 on its own when busy."
pause "Press Enter to continue"


# ── Stage 6: start dev servers ────────────────────────────────────────────
stage "Start dev servers"
say "API  → http://localhost:$api_port"
say "Web  → http://localhost:$web_port"
say "Native Metro on :$metro_port (Expo Go or an emulator)"
say "Database: $db_name"
note "Concurrent worktrees use their own slot and database; re-runs keep this one."
if confirm "Start \`pnpm dev\` now?"; then
  say "Ctrl-C stops them all. Restart any time with \`pnpm dev\`."
  exec pnpm dev
fi

summary
